state = {'min': None, 'max': None}

def rpc(cmd, args, ctx):
    hal = ctx['hal']
    if cmd == 'read':
        t = hal.get_temperature_c()
        if t is not None:
            if state['min'] is None or t < state['min']:
                state['min'] = t
            if state['max'] is None or t > state['max']:
                state['max'] = t
        return {'temp_c': t, 'min': state['min'], 'max': state['max'], 'board': hal.board_name}
    if cmd == 'reset':
        state['min'] = None
        state['max'] = None
        return {'ok': True}
    raise ValueError('Comando desconocido: ' + str(cmd))

