(function () {
  MicroOS.wm.registerApp({
    id: 'termometro',
    title: 'Termometro MCU',
    icon: '🌡️',
    width: 340,
    height: 250,
    mount(container) {
      const { client, toast } = MicroOS;
      container.innerHTML = `
        <div class='card' style='display:flex;flex-direction:column;gap:10px;text-align:center;'>
          <div class='muted' id='th-board'>Leyendo sensor...</div>
          <div class='mono' id='th-val' style='font-size:36px;font-weight:700;'>-- °C</div>
          <div style='height:10px;background:rgba(2,6,23,0.7);border-radius:6px;overflow:hidden;'>
            <div id='th-bar' style='height:100%;width:0%;background:linear-gradient(90deg,#38bdf8,#f59e0b,#ef4444);transition:width 0.3s;'></div>
          </div>
          <div class='mono muted' id='th-mm' style='font-size:12px;'>Min: -- °C · Max: -- °C</div>
          <div style='display:flex;gap:8px;justify-content:center;'>
            <button class='btn primary' id='th-ref'>Leer ahora</button>
            <button class='btn' id='th-rst'>Reiniciar Min/Max</button>
          </div>
        </div>
      `;
      const elVal = container.querySelector('#th-val');
      const elBar = container.querySelector('#th-bar');
      const elMm = container.querySelector('#th-mm');
      const elBoard = container.querySelector('#th-board');

      async function poll() {
        try {
          const r = await client.call('termometro', 'read');
          elBoard.textContent = r.board;
          if (r.temp_c === null) {
            elVal.textContent = 'N/A';
            return;
          }
          elVal.textContent = `${r.temp_c.toFixed(1)} °C`;
          elBar.style.width = `${Math.min(100, Math.max(0, r.temp_c))}%`;
          elMm.textContent = `Min: ${r.min.toFixed(1)} °C · Max: ${r.max.toFixed(1)} °C`;
        } catch (e) {
          toast(e.message, 'err');
        }
      }

      container.querySelector('#th-ref').onclick = poll;
      container.querySelector('#th-rst').onclick = async () => {
        await client.call('termometro', 'reset');
        poll();
      };

      poll();
      const timer = setInterval(poll, 2000);
      return () => clearInterval(timer);
    }
  });
})();
